import{_ as a,o,c as s,a3 as i}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Espelho dos Critérios de Pesquisa de Certidão","description":"","frontmatter":{"title":"Espelho dos Critérios de Pesquisa de Certidão","id":"rupe-espelho-painel-pesquisa","plataforma":"RUPE","grupo":"RUPE","plano":"free","desde":"1.0.2","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/rupe-espelho-painel-pesquisa.md","filePath":"funcionalidades/rupe-espelho-painel-pesquisa.md"}'),r={name:"funcionalidades/rupe-espelho-painel-pesquisa.md"};function t(d,e,c,n,l,u){return o(),s("div",null,e[0]||(e[0]=[i('<h1 id="espelho-dos-criterios-de-pesquisa-de-certidao" tabindex="-1">Espelho dos Critérios de Pesquisa de Certidão <a class="header-anchor" href="#espelho-dos-criterios-de-pesquisa-de-certidao" aria-label="Permalink to &quot;Espelho dos Critérios de Pesquisa de Certidão&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na emissão de certidão positiva/negativa do RUPE, os critérios da pesquisa somem da vista quando os resultados aparecem. Este recurso mantém os critérios num painel flutuante e destaca, na tabela de pessoas encontradas, o que coincide com eles, inclusive nomes com pequenas variações de grafia.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>RUPE</strong> (<code>rupe.tjmg.jus.br</code>), tela de emissão de certidão positiva/negativa.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Faça a pesquisa de certidão normalmente.</li><li>O painel &quot;Critérios de pesquisa&quot; mostra o que foi pesquisado. Arraste-o pelo título para onde preferir. O botão &quot;–&quot; recolhe o painel num ícone, que pode ser arrastado ou clicado para expandir.</li><li>Na aba &quot;Pessoas&quot;, os valores que coincidem com os critérios ficam destacados nos dois lados, com uma cor para cada critério. Passe o mouse sobre um critério para destacar só ele.</li><li>Nomes parecidos (sem acento, com &quot;da&quot;/&quot;dos&quot;, Luiz/Luis, pequenos erros) também coincidem, com o trecho diferente em vermelho. Um selo indica se a coincidência é perfeita ou parcial.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Destacar equivalências entre o painel e a tabela de pessoas encontradas</td><td>ligada</td><td>Liga os destaques coloridos.</td></tr><tr><td>Marcar automaticamente o registro que é sem dúvida a pessoa pesquisada (mesmo CPF/CNPJ)</td><td>desligada</td><td>Marca sozinho o registro com o mesmo CPF/CNPJ pesquisado.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A coincidência aproximada de nomes é um auxílio. A decisão sobre a certidão continua sendo sua: confira sempre os dados.</li><li>A marcação automática só acontece quando o CPF/CNPJ é exatamente o pesquisado.</li></ul>',11)]))}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
